begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','save_staff_order_draft',array['uuid','uuid','uuid','uuid','integer','jsonb'],'native order draft save exists');
select ok(not has_table_privilege('anon','public.orders','SELECT'),'anonymous cannot read buyer PII');
select ok(not has_table_privilege('authenticated','public.order_items','SELECT'),'browser cannot read order items');
select ok(not has_function_privilege('service_role','public.freeze_order_checkout_snapshot(uuid,uuid,integer,uuid)','EXECUTE'),'freeze helper is integration-only');
insert into public.organizations(id,name,slug) values('a2000000-0000-4000-8000-000000000001','Order test fixture','order-test-fixture');
insert into auth.users(id) values('b2000000-0000-4000-8000-000000000001');
insert into public.staff_profiles(user_id,organization_id,role,active) values('b2000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','staff',true);
insert into public.products(id,organization_id,source_name,source_url,canonical_url,name,price_vnd,stock_quantity,in_stock,quality) values
('c2000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Fixture','urn:test:order-parent','urn:test:order-parent','Fixture parent',100000,10,true,'partial'),
('c2000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000001','Fixture','urn:test:order-variant-parent','urn:test:order-variant-parent','Fixture variants',100000,10,true,'partial');
insert into public.product_variants(id,product_id,name,price_vnd,stock_quantity,in_stock) values('c2000000-0000-4000-8000-000000000003','c2000000-0000-4000-8000-000000000002','Variant',250000,10,true);
create temporary table order_fixture(document jsonb);
insert into order_fixture values('{"buyerName":"Test buyer","phone":"+84900000000","address":{"line1":"Test street","ward":null,"district":null,"province":"Test city","countryCode":"VN"},"items":[{"productId":"c2000000-0000-4000-8000-000000000001","variantId":null,"quantity":2},{"productId":"c2000000-0000-4000-8000-000000000002","variantId":"c2000000-0000-4000-8000-000000000003","quantity":3}]}');
grant select on order_fixture to service_role;
create function pg_temp.save_order(ver integer,doc jsonb default null,request uuid default gen_random_uuid(),target uuid default 'd2000000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select public.save_staff_order_draft('a2000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001',target,request,ver,coalesce(doc,(select document from order_fixture)))
$$;
set local role service_role;
select lives_ok($$select pg_temp.save_order(0,null,'e2000000-0000-4000-8000-000000000001')$$,'staff saves native draft');
select is((select count(*) from public.order_items where order_id='d2000000-0000-4000-8000-000000000001'),2::bigint,'items saved atomically');
select is((select subtotal_vnd from public.orders where id='d2000000-0000-4000-8000-000000000001'),950000::bigint,'server uses variant price rather than parent price');
select is((select shipping_fee_vnd from public.orders where id='d2000000-0000-4000-8000-000000000001'),null::bigint,'missing shipping remains unknown');
select is((select total_vnd from public.orders where id='d2000000-0000-4000-8000-000000000001'),null::bigint,'unknown shipping does not imply free delivery');
select lives_ok($$select pg_temp.save_order(0,null,'e2000000-0000-4000-8000-000000000001')$$,'identical request is idempotent');
select is((select count(*) from public.audit_events where entity_id='d2000000-0000-4000-8000-000000000001'),1::bigint,'idempotent request adds no second audit');
select throws_ok($$select pg_temp.save_order(0,(select document||'{"buyerName":"Other"}' from order_fixture),'e2000000-0000-4000-8000-000000000001')$$,'40001','ORDER_REQUEST_CONFLICT','request ID cannot be reused with changed buyer');
select throws_ok($$select pg_temp.save_order(0)$$,'40001','ORDER_VERSION_CONFLICT','stale draft cannot overwrite newer version');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"shippingFeeVnd":0}' from order_fixture))$$,'22023','ORDER_INVALID','payload cannot set shipping fee');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"items":[{"productId":"c2000000-0000-4000-8000-000000000001","variantId":null,"quantity":1,"unitPriceVnd":1}]}' from order_fixture))$$,'22023','ORDER_INVALID','payload cannot set price');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"items":[{"productId":"c2000000-0000-4000-8000-000000000001","variantId":null,"quantity":-1}]}' from order_fixture))$$,'22023','ORDER_INVALID','negative quantity rejected');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"phone":"not-a-phone"}' from order_fixture))$$,'22023','ORDER_INVALID','invalid phone rejected');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"address":{"line1":"","ward":null,"district":null,"province":"Test","countryCode":"VN"}}' from order_fixture))$$,'22023','ORDER_INVALID','invalid address rejected');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"address":{"line1":null,"ward":null,"district":null,"province":"Test","countryCode":"VN"}}' from order_fixture))$$,'22023','ORDER_INVALID','null required address field rejected');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"items":[{"productId":"c2000000-0000-4000-8000-000000000002","variantId":null,"quantity":1}]}' from order_fixture))$$,'22023','ORDER_VARIANT_REQUIRED','parent cannot be sold beside variant inventory');
select is((select revision from public.orders where id='d2000000-0000-4000-8000-000000000001'),1,'rejected saves leave revision intact');
select is((select count(*) from public.order_items where order_id='d2000000-0000-4000-8000-000000000001'),2::bigint,'failed item replacement rolls back old items');
select is(public.read_staff_order('a2000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001')->>'buyerName','Test buyer','authorized staff can read buyer');
select throws_ok($$select public.read_staff_order('a0000000-0000-0000-0000-000000000001','b2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001')$$,'42501','ORDER_FORBIDDEN','foreign organization cannot read PII');
select lives_ok($$select public.save_automation_order_draft('a2000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001',null,'d2000000-0000-4000-8000-000000000002',gen_random_uuid(),0,(select document from order_fixture))$$,'trusted automation creates unknown-source draft');
select is((select conversation_id from public.orders where id='d2000000-0000-4000-8000-000000000002'),null::uuid,'unknown provenance remains null');
select throws_ok($$select public.read_automation_order('a2000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000099','d2000000-0000-4000-8000-000000000002')$$,'42501','ORDER_FORBIDDEN','another automation workflow cannot read PII');
select throws_ok($$select public.save_automation_order_draft('a2000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000099',null,'d2000000-0000-4000-8000-000000000002',gen_random_uuid(),1,(select document from order_fixture))$$,'42501','ORDER_FORBIDDEN','another automation workflow cannot edit');
select throws_ok($$select public.save_automation_order_draft('a2000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001',null,'d2000000-0000-4000-8000-000000000001',gen_random_uuid(),1,(select document from order_fixture))$$,'42501','ORDER_FORBIDDEN','automation cannot take over staff order');
reset role;
select throws_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',1,gen_random_uuid())$$,'22023','ORDER_SHIPPING_UNKNOWN','unknown fee blocks checkout boundary');
insert into public.order_shipping_settings(organization_id,flat_fee_vnd) values('a2000000-0000-4000-8000-000000000001',30000);
select throws_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',1,gen_random_uuid())$$,'40001','ORDER_SHIPPING_CHANGED','new fee must be shown in a refreshed draft');
select lives_ok($$select pg_temp.save_order(1)$$,'refresh draft with configured fee');
select is((select total_vnd from public.orders where id='d2000000-0000-4000-8000-000000000001'),980000::bigint,'total includes server-configured fee');
update public.products set price_vnd=110000,version=version+1 where id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',2,gen_random_uuid())$$,'40001','ORDER_CATALOG_CHANGED','price/version change requires reconfirmation');
select lives_ok($$select pg_temp.save_order(2)$$,'refresh authoritative prices');
select is((select subtotal_vnd from public.orders where id='d2000000-0000-4000-8000-000000000001'),970000::bigint,'refresh uses new catalog price');
update public.order_shipping_settings set flat_fee_vnd=40000 where organization_id='a2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',3,gen_random_uuid())$$,'40001','ORDER_SHIPPING_CHANGED','fee revision fences checkout');
select lives_ok($$select pg_temp.save_order(3)$$,'refresh latest fee');
select lives_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',4,'e2000000-0000-4000-8000-000000000050')$$,'integration transaction freezes snapshot');
select is((select fulfilment_status from public.orders where id='d2000000-0000-4000-8000-000000000001'),'DRAFT','freeze does not start payment or reservation');
select lives_ok($$select public.freeze_order_checkout_snapshot('a2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',4,'e2000000-0000-4000-8000-000000000050')$$,'same freeze request replays snapshot');
select throws_ok($$select pg_temp.save_order(5)$$,'55000','ORDER_FROZEN','frozen draft cannot be edited');
select throws_ok($$update public.orders set buyer_name='Overwrite' where id='d2000000-0000-4000-8000-000000000001'$$,'55000','ORDER_FROZEN','database trigger preserves frozen buyer');
select throws_ok($$update public.order_items set name='Overwrite' where order_id='d2000000-0000-4000-8000-000000000001'$$,'55000','ORDER_FROZEN','database trigger preserves frozen items');
select throws_ok($$delete from public.order_items where order_id='d2000000-0000-4000-8000-000000000001'$$,'55000','ORDER_FROZEN','frozen lines cannot be deleted');
update public.products set price_vnd=999999 where id='c2000000-0000-4000-8000-000000000001';
select is((select unit_price_vnd from public.order_items where order_id='d2000000-0000-4000-8000-000000000001' and line_number=1),110000::bigint,'later catalog changes do not rewrite frozen line price');
select is((select checkout_snapshot->>'totalVnd' from public.orders where id='d2000000-0000-4000-8000-000000000001'),'1010000','frozen total remains historical');
update public.products set disabled_at=clock_timestamp() where id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.save_order(1,null,gen_random_uuid(),'d2000000-0000-4000-8000-000000000002')$$,'22023','ORDER_PRODUCT_UNAVAILABLE','disabled product cannot enter draft');
update public.products set disabled_at=null,price_vnd=110000 where id='c2000000-0000-4000-8000-000000000001';
update public.product_variants set disabled_at=clock_timestamp() where id='c2000000-0000-4000-8000-000000000003';
select throws_ok($$select pg_temp.save_order(1,null,gen_random_uuid(),'d2000000-0000-4000-8000-000000000002')$$,'22023','ORDER_PRODUCT_UNAVAILABLE','disabled variant cannot enter draft');
update public.product_variants set disabled_at=null where id='c2000000-0000-4000-8000-000000000003';
update public.products set price_vnd=9007199254740991 where id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.save_order(1,null,gen_random_uuid(),'d2000000-0000-4000-8000-000000000002')$$,'22023','ORDER_AMOUNT_OVERFLOW','server rejects unsafe integer totals');
update public.products set price_vnd=110000 where id='c2000000-0000-4000-8000-000000000001';
insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values('a2000000-0000-4000-8000-000000000001','system','test.fixture','order','d2000000-0000-4000-8000-000000000002','test.fixture','e2000000-0000-4000-8000-000000000099','e2000000-0000-4000-8000-000000000099');
select throws_ok($$select pg_temp.save_order(1,(select document||'{"buyerName":"MUST ROLLBACK"}' from order_fixture),'e2000000-0000-4000-8000-000000000099','d2000000-0000-4000-8000-000000000002')$$,'23505',null,'audit failure aborts order and item replacement');
select is((select revision from public.orders where id='d2000000-0000-4000-8000-000000000002'),1,'audit failure rolls back revision');
select is((select buyer_name from public.orders where id='d2000000-0000-4000-8000-000000000002'),'Test buyer','audit failure rolls back buyer');
select is((select unit_price_vnd from public.order_items where order_id='d2000000-0000-4000-8000-000000000002' and line_number=1),100000::bigint,'audit failure rolls back repriced items');
update public.staff_profiles set active=false where user_id='b2000000-0000-4000-8000-000000000001';
set local role service_role;
select throws_ok($$select public.read_staff_order('a2000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001')$$,'42501','ORDER_FORBIDDEN','disabled profile cannot read PII');
select throws_ok($$select pg_temp.save_order(0,null,'e2000000-0000-4000-8000-000000000001')$$,'42501','ORDER_FORBIDDEN','disabled profile cannot replay a draft save');
reset role;
select * from finish();
rollback;
